import math


def carico_critico(E, I, L, beta=1.0):
    return math.pi**2 * E * I / (beta * L) ** 2


def snellezza(L, i, beta=1.0):
    return beta * L / i


def verifica_instabilita(N, E, I, L, beta=1.0):
    return N < carico_critico(E, I, L, beta)

import math


def bisezione(f, a, b, tol=1e-8):
    fa, fb = f(a), f(b)
    if fa * fb > 0:
        raise ValueError("f(a) e f(b) devono avere segno opposto")
    while b - a > tol:
        m = (a + b) / 2
        fm = f(m)
        if fa * fm <= 0:
            b, fb = m, fm
        else:
            a, fa = m, fm
    return (a + b) / 2


def diametro_minimo(F, sigma_amm):
    return bisezione(lambda d: 4 * F / (math.pi * d**2) - sigma_amm, 0.1, 1000)

def media(xs):
    return sum(xs) / len(xs)


def dev_std(xs):
    m = media(xs)
    return (sum((x - m) ** 2 for x in xs) / (len(xs) - 1)) ** 0.5


def fuori_soglia(xs, k=2):
    m, s = media(xs), dev_std(xs)
    return [x for x in xs if abs(x - m) > k * s]

def massa_totale(distinta):
    tot = 0.0
    for voce in distinta.values():
        unit = voce.get("massa", 0.0) + massa_totale(voce.get("sotto", {}))
        tot += voce["qta"] * unit
    return tot


def conta_pezzi(distinta, molt=1, acc=None):
    acc = {} if acc is None else acc
    for nome, voce in distinta.items():
        n = molt * voce["qta"]
        acc[nome] = acc.get(nome, 0) + n
        conta_pezzi(voce.get("sotto", {}), n, acc)
    return acc

